@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --paper: #faf8f5;
  --ink: #2b1810;
  --accent: #c96442;
  --line: #e5ddcc;
}

html,
body {
  background-color: var(--paper);
  color: var(--ink);
  font-feature-settings: "kern", "liga", "calt";
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "Source Serif 4", "Source Serif Pro", Georgia, Cambria,
    "Times New Roman", serif;
  font-size: 15px;
  line-height: 1.6;
  letter-spacing: 0.005em;
}

/* Subtle paper grain for the page background */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(
      rgba(43, 24, 16, 0.025) 1px,
      transparent 1px
    );
  background-size: 4px 4px;
  z-index: 0;
}

/* Hide number input spinners */
input[type="number"]::-webkit-inner-spin-button,
input[type="number"]::-webkit-outer-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type="number"] {
  -moz-appearance: textfield;
}

/* Inline editor focus ring (subtle) */
.cell-input:focus {
  outline: none;
  box-shadow: inset 0 0 0 1.5px var(--accent);
  background-color: #fcfaf6;
}

.cell-input.cell-input--readonly {
  color: var(--ink);
  opacity: 0.55;
  cursor: not-allowed;
  background-color: transparent;
}
.cell-input.cell-input--readonly:focus {
  box-shadow: none;
  background-color: transparent;
}

/* Modal overlay */
.modal-overlay {
  background-color: rgba(31, 20, 16, 0.32);
  backdrop-filter: blur(2px);
}

/* Print-friendly table */
@media print {
  body::before {
    display: none;
  }
}

import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "医用耗材录入表",
  description: "本地存储的医用耗材请购单编辑器，一键导出截图",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="zh-CN">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link
          rel="preconnect"
          href="https://fonts.gstatic.com"
          crossOrigin="anonymous"
        />
        <link
          href="https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,300;8..60,400;8..60,500;8..60,600;8..60,700&display=swap"
          rel="stylesheet"
        />
      </head>
      <body>{children}</body>
    </html>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import TableEditor from "@/components/TableEditor";
import AddItemModal from "@/components/AddItemModal";
import ExportButton from "@/components/ExportButton";
import type { Item } from "@/types/item";
import { FIXED_QTY, FIXED_UNIT } from "@/types/item";
import { loadItems, saveItems, nextNo } from "@/lib/storage";

export default function Page() {
  const [items, setItems] = useState<Item[]>([]);
  const [hydrated, setHydrated] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Item | null>(null);
  const tableWrapRef = useRef<HTMLDivElement>(null);

  // Hydrate from localStorage on mount
  useEffect(() => {
    setItems(loadItems());
    setHydrated(true);
  }, []);

  // Persist on change
  useEffect(() => {
    if (hydrated) saveItems(items);
  }, [items, hydrated]);

  const handleAdd = useCallback(
    (data: Omit<Item, "id" | "qty" | "unit">) => {
      setItems((prev) => [
        ...prev,
        {
          id: uuidv4(),
          spd: data.spd,
          no: data.no,
          name: data.name,
          spec: data.spec,
          qty: FIXED_QTY,
          unit: FIXED_UNIT,
          remark: data.remark,
        },
      ]);
    },
    []
  );

  const handleChange = useCallback((id: string, patch: Partial<Item>) => {
    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, ...patch } : it)));
  }, []);

  const handleRemove = useCallback((id: string) => {
    setItems((prev) => {
      const filtered = prev.filter((it) => it.id !== id);
      // Re-number sequentially to keep 序号 tidy
      return filtered.map((it, i) => ({ ...it, no: i + 1 }));
    });
  }, []);

  const handleClear = () => {
    if (items.length === 0) return;
    if (
      confirm(
        `确定清空全部 ${items.length} 条记录？此操作不可恢复（仅清除本地浏览器数据）。`
      )
    ) {
      setItems([]);
    }
  };

  const computedNextNo = useMemo(() => nextNo(items), [items]);

  return (
    <main className="relative min-h-screen px-4 sm:px-8 py-8 sm:py-12 max-w-[1280px] mx-auto">
      {/* Header */}
      <header className="mb-8">
        <p className="text-sm text-ink-500 tracking-widest uppercase mb-1">
          Medical Supplies · Local Editor
        </p>
        <h1
          className="text-[34px] sm:text-[40px] font-semibold text-ink-900 leading-tight"
          style={{ letterSpacing: "0.005em" }}
        >
          医用耗材录入表
        </h1>
        <p className="text-ink-600 mt-2 max-w-2xl">
          数据保存在本机浏览器，刷新不丢失。点击表格单元格即可就地编辑；
          点击「导出截图」可一键下载为 PNG 图片。
        </p>
      </header>

      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
        <div className="text-sm text-ink-600">
          <span className="text-ink-500">共 </span>
          <span className="font-semibold text-ink-900 tabular-nums">
            {items.length}
          </span>
          <span className="text-ink-500"> 条记录</span>
          {items.length > 0 && (
            <span className="text-ink-400 ml-3">
              （请购数固定 {FIXED_QTY} {FIXED_UNIT}/条）
            </span>
          )}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={() => {
              setEditing(null);
              setModalOpen(true);
            }}
            className="inline-flex items-center gap-2 rounded-md px-4 py-2 text-sm font-medium text-paper-50 bg-accent hover:bg-accent-hover transition-colors shadow-soft"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="12" y1="5" x2="12" y2="19" />
              <line x1="5" y1="12" x2="19" y2="12" />
            </svg>
            添加条目
          </button>
          <ExportButton targetRef={tableWrapRef} />
          {items.length > 0 && (
            <button
              onClick={handleClear}
              className="rounded-md px-3 py-2 text-sm text-ink-600 hover:text-accent hover:bg-paper-200 transition-colors"
            >
              清空全部
            </button>
          )}
        </div>
      </div>

      {/* Table region (the part to be captured) */}
      <div ref={tableWrapRef} className="bg-paper-100 p-2 sm:p-3 rounded-2xl">
        <TableEditor
          items={items}
          onChange={handleChange}
          onRemove={handleRemove}
        />
      </div>

      {/* Footer note */}
      <footer className="mt-10 pt-6 border-t border-line/60 text-sm text-ink-500 flex flex-wrap items-center justify-between gap-2">
        <p>
          序号自动递增，删除条目后会自动重新编号。SPD 编码可留空。
        </p>
        <p className="text-ink-400">
          数据仅存储于本机浏览器，不会上传服务器。
        </p>
      </footer>

      <AddItemModal
        open={modalOpen}
        initial={editing}
        nextNo={computedNextNo}
        onClose={() => {
          setModalOpen(false);
          setEditing(null);
        }}
        onSave={(data) => {
          if (editing) {
            handleChange(editing.id, {
              spd: data.spd,
              name: data.name,
              spec: data.spec,
              remark: data.remark,
            });
          } else {
            handleAdd(data);
          }
          setEditing(null);
        }}
      />
    </main>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { Item } from "@/types/item";
import { FIXED_QTY, FIXED_UNIT } from "@/types/item";

interface Props {
  open: boolean;
  initial?: Partial<Item> | null;
  nextNo: number;
  onClose: () => void;
  onSave: (data: Omit<Item, "id" | "no" | "qty" | "unit"> & { no: number }) => void;
}

export default function AddItemModal({
  open,
  initial,
  nextNo,
  onClose,
  onSave,
}: Props) {
  const [spd, setSpd] = useState("");
  const [name, setName] = useState("");
  const [spec, setSpec] = useState("");
  const [remark, setRemark] = useState("");
  const [error, setError] = useState<string | null>(null);
  const nameRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (open) {
      setSpd(initial?.spd ?? "");
      setName(initial?.name ?? "");
      setSpec(initial?.spec ?? "");
      setRemark(initial?.remark ?? "");
      setError(null);
      // Focus name field on open
      setTimeout(() => nameRef.current?.focus(), 30);
    }
  }, [open, initial]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      setError("品名不能为空");
      return;
    }
    if (!spec.trim()) {
      setError("规格不能为空");
      return;
    }
    onSave({
      spd: spd.trim(),
      no: initial?.no ?? nextNo,
      name: name.trim(),
      spec: spec.trim(),
      remark: remark.trim(),
    });
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center modal-overlay"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <form
        onSubmit={handleSubmit}
        className="relative w-[min(560px,92vw)] rounded-2xl bg-paper-50 shadow-card border border-line/60 p-7"
        style={{ fontFamily: "inherit" }}
      >
        <h2
          className="text-[22px] font-semibold text-ink-900 tracking-tight"
          style={{ letterSpacing: "0.01em" }}
        >
          {initial?.id ? "编辑条目" : "添加条目"}
        </h2>
        <p className="text-sm text-ink-500 mt-1 mb-5">
          请购数与单位已固定为「{FIXED_QTY} {FIXED_UNIT}」，无需填写。
        </p>

        <div className="space-y-3">
          <Field label="SPD">
            <input
              value={spd}
              onChange={(e) => setSpd(e.target.value)}
              placeholder="如 SPD-2026-001（可留空）"
              className="cell-input w-full rounded-md border border-line bg-paper-50 px-3 py-2 text-ink-800"
            />
          </Field>
          <Field label="品名" required>
            <input
              ref={nameRef}
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="如 冠龙PVP器械"
              className="cell-input w-full rounded-md border border-line bg-paper-50 px-3 py-2 text-ink-800"
            />
          </Field>
          <Field label="规格" required>
            <textarea
              value={spec}
              onChange={(e) => setSpec(e.target.value)}
              rows={2}
              placeholder="如 经皮L3、L4、L5椎体成形术"
              className="cell-input w-full rounded-md border border-line bg-paper-50 px-3 py-2 text-ink-800 resize-y"
            />
          </Field>
          <div className="grid grid-cols-2 gap-3">
            <Field label="请购数">
              <input
                value={FIXED_QTY}
                readOnly
                className="cell-input cell-input--readonly w-full rounded-md border border-line bg-paper-100 px-3 py-2"
              />
            </Field>
            <Field label="单位">
              <input
                value={FIXED_UNIT}
                readOnly
                className="cell-input cell-input--readonly w-full rounded-md border border-line bg-paper-100 px-3 py-2"
              />
            </Field>
          </div>
          <Field label="备注">
            <textarea
              value={remark}
              onChange={(e) => setRemark(e.target.value)}
              rows={2}
              placeholder="如 许惠刁、565214、骨三王伟豪"
              className="cell-input w-full rounded-md border border-line bg-paper-50 px-3 py-2 text-ink-800 resize-y"
            />
          </Field>
        </div>

        {error && (
          <p className="mt-3 text-sm text-accent">{error}</p>
        )}

        <div className="mt-6 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="rounded-md px-4 py-2 text-sm text-ink-700 hover:bg-paper-200 transition-colors"
          >
            取消
          </button>
          <button
            type="submit"
            className="rounded-md px-4 py-2 text-sm font-medium text-paper-50 bg-accent hover:bg-accent-hover transition-colors shadow-soft"
          >
            {initial?.id ? "保存修改" : "添加到列表"}
          </button>
        </div>
      </form>
    </div>
  );
}

function Field({
  label,
  required,
  children,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
}) {
  return (
    <label className="block">
      <span className="block text-xs font-medium text-ink-600 mb-1 tracking-wide">
        {label}
        {required && <span className="text-accent ml-0.5">*</span>}
      </span>
      {children}
    </label>
  );
}

"use client";

import { useState } from "react";

interface Props {
  targetRef: React.RefObject<HTMLElement>;
  filename?: string;
}

export default function ExportButton({ targetRef, filename }: Props) {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const handleClick = async () => {
    if (!targetRef.current) return;
    setBusy(true);
    setErr(null);
    try {
      const html2canvas = (await import("html2canvas")).default;
      const node = targetRef.current;
      const canvas = await html2canvas(node, {
        backgroundColor: "#faf8f5",
        scale: 2,
        useCORS: true,
        logging: false,
        // Avoid clipping wide tables on small viewports
        windowWidth: Math.max(node.scrollWidth, document.documentElement.clientWidth),
      });
      const dataUrl = canvas.toDataURL("image/png");
      const a = document.createElement("a");
      const stamp = new Date()
        .toISOString()
        .replace(/[-:]/g, "")
        .replace(/\..+/, "")
        .replace("T", "-");
      a.href = dataUrl;
      a.download = (filename || `医用耗材录入表-${stamp}`) + ".png";
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (e) {
      console.error(e);
      setErr("截图失败，请重试");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="inline-flex items-center gap-2">
      <button
        onClick={handleClick}
        disabled={busy}
        className="inline-flex items-center gap-2 rounded-md px-4 py-2 text-sm font-medium text-paper-50 bg-ink-800 hover:bg-ink-700 disabled:opacity-60 transition-colors shadow-soft"
        title="仅导出表格主体"
      >
        {busy ? (
          <>
            <span className="inline-block w-3 h-3 rounded-full border-2 border-paper-50 border-t-transparent animate-spin" />
            正在截图…
          </>
        ) : (
          <>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
              <polyline points="7 10 12 15 17 10" />
              <line x1="12" y1="15" x2="12" y2="3" />
            </svg>
            一键导出截图
          </>
        )}
      </button>
      {err && <span className="text-xs text-accent">{err}</span>}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { Item } from "@/types/item";
import { FIXED_QTY, FIXED_UNIT } from "@/types/item";

interface Props {
  items: Item[];
  onChange: (id: string, patch: Partial<Item>) => void;
  onRemove: (id: string) => void;
}

export default function TableEditor({ items, onChange, onRemove }: Props) {
  if (items.length === 0) {
    return (
      <div className="rounded-xl border border-dashed border-line bg-paper-50 py-16 text-center">
        <p className="text-ink-500 text-base">尚无条目</p>
        <p className="text-ink-400 text-sm mt-1">
          点击右上角「添加条目」开始录入第一条耗材信息
        </p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto rounded-xl border border-line bg-paper-50 shadow-card">
      <table className="w-full border-collapse text-[14.5px]">
        <colgroup>
          <col style={{ width: "10%" }} />   {/* SPD */}
          <col style={{ width: "6%" }} />    {/* 序号 */}
          <col style={{ width: "18%" }} />   {/* 品名 */}
          <col style={{ width: "28%" }} />   {/* 规格 */}
          <col style={{ width: "8%" }} />    {/* 请购数 */}
          <col style={{ width: "6%" }} />    {/* 单位 */}
          <col style={{ width: "20%" }} />   {/* 备注 */}
          <col style={{ width: "4%" }} />    {/* × */}
        </colgroup>
        <thead>
          <tr className="bg-paper-200/70 text-ink-700">
            <Th>SPD</Th>
            <Th>序号</Th>
            <Th>品名</Th>
            <Th>规格</Th>
            <Th>请购数</Th>
            <Th>单位</Th>
            <Th>备注</Th>
            <Th className="!text-center">×</Th>
          </tr>
        </thead>
        <tbody>
          {items.map((it, idx) => (
            <tr
              key={it.id}
              className={
                "border-t border-line/70 " +
                (idx % 2 === 1 ? "bg-paper-100/40 " : "bg-paper-50 ") +
                "hover:bg-accent-soft/30 transition-colors"
              }
            >
              <Cell
                value={it.spd}
                onCommit={(v) => onChange(it.id, { spd: v })}
                placeholder="—"
              />
              <Cell
                value={String(it.no)}
                readOnly
                className="text-ink-500 tabular-nums"
              />
              <Cell
                value={it.name}
                onCommit={(v) => onChange(it.id, { name: v })}
                placeholder="未填写"
                required
              />
              <Cell
                value={it.spec}
                onCommit={(v) => onChange(it.id, { spec: v })}
                multiline
                placeholder="未填写"
                required
              />
              <Cell
                value={String(FIXED_QTY)}
                readOnly
                className="text-ink-500 tabular-nums"
              />
              <Cell value={FIXED_UNIT} readOnly className="text-ink-500" />
              <Cell
                value={it.remark}
                onCommit={(v) => onChange(it.id, { remark: v })}
                multiline
                placeholder="—"
              />
              <td className="px-2 py-2 text-center align-top">
                <button
                  onClick={() => {
                    if (confirm(`确定删除「${it.name || "此条目"}」？`)) {
                      onRemove(it.id);
                    }
                  }}
                  className="text-ink-400 hover:text-accent transition-colors text-lg leading-none"
                  title="删除该条"
                  aria-label="删除"
                >
                  ×
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function Th({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <th
      className={
        "px-3 py-2.5 text-left font-semibold tracking-wide text-[13px] " +
        className
      }
      style={{ letterSpacing: "0.04em" }}
    >
      {children}
    </th>
  );
}

interface CellProps {
  value: string;
  onCommit?: (v: string) => void;
  readOnly?: boolean;
  multiline?: boolean;
  placeholder?: string;
  required?: boolean;
  className?: string;
}

function Cell({
  value,
  onCommit,
  readOnly,
  multiline,
  placeholder,
  required,
  className = "",
}: CellProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const ref = useRef<HTMLInputElement | HTMLTextAreaElement>(null);

  useEffect(() => {
    if (!editing) setDraft(value);
  }, [value, editing]);

  useEffect(() => {
    if (editing) {
      const el = ref.current;
      if (!el) return;
      el.focus();
      // place caret at end
      const len = el.value.length;
      if (el instanceof HTMLInputElement) {
        el.setSelectionRange(len, len);
      } else {
        el.selectionStart = el.selectionEnd = len;
      }
    }
  }, [editing]);

  const commit = () => {
    setEditing(false);
    if (onCommit && draft !== value) onCommit(draft);
  };

  const cancel = () => {
    setDraft(value);
    setEditing(false);
  };

  if (readOnly) {
    return (
      <td
        className={
          "px-3 py-2.5 align-top whitespace-pre-wrap break-words " + className
        }
      >
        {value}
      </td>
    );
  }

  if (editing) {
    const base =
      "w-full bg-paper-50 px-2 py-1.5 rounded-sm border-0 outline-none ring-2 ring-accent text-ink-900";
    return (
      <td className="px-2 py-1.5 align-top">
        {multiline ? (
          <textarea
            ref={ref as React.RefObject<HTMLTextAreaElement>}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onBlur={commit}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
                e.preventDefault();
                commit();
              } else if (e.key === "Escape") {
                e.preventDefault();
                cancel();
              }
            }}
            rows={Math.min(6, Math.max(2, draft.split("\n").length))}
            className={base + " resize-y min-h-[2.4em] leading-relaxed"}
          />
        ) : (
          <input
            ref={ref as React.RefObject<HTMLInputElement>}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onBlur={commit}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                commit();
              } else if (e.key === "Escape") {
                e.preventDefault();
                cancel();
              }
            }}
            className={base}
          />
        )}
      </td>
    );
  }

  const empty = !value.trim();
  return (
    <td
      className={
        "px-3 py-2.5 align-top whitespace-pre-wrap break-words cursor-text " +
        className
      }
      onClick={() => setEditing(true)}
      title={required && empty ? "必填" : "点击编辑"}
    >
      {empty ? (
        <span className="text-ink-400 italic">{placeholder ?? "点击填写"}</span>
      ) : (
        <span>{value}</span>
      )}
    </td>
  );
}

import type { Item } from "@/types/item";

const KEY = "medical-supplies-table.items.v1";

export function loadItems(): Item[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (x) => x && typeof x.id === "string" && typeof x.name === "string"
    );
  } catch {
    return [];
  }
}

export function saveItems(items: Item[]): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(KEY, JSON.stringify(items));
  } catch {
    /* ignore quota errors */
  }
}

export function nextNo(items: Item[]): number {
  if (items.length === 0) return 1;
  return Math.max(...items.map((i) => i.no)) + 1;
}

